package com.example.jobfinderapp.activities;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.*;import androidx.recyclerview.widget.*;import com.example.jobfinderapp.R;import com.example.jobfinderapp.database.DBHelper;import com.example.jobfinderapp.models.User;import com.example.jobfinderapp.utils.UserSession;import com.example.jobfinderapp.adapters.AdminJobAdapter;import java.util.*;
public class AdminManageJobsActivity extends AppCompatActivity{DBHelper db;int admin;List<Map<String,Object>>rows=new ArrayList<>();public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_admin_manage_jobs);db=DBHelper.getInstance(this);UserSession s=new UserSession(this);admin=s.getUserId();User u=db.getUserById(admin);if(u==null||!DBHelper.ROLE_ADMIN.equals(u.getRole())||!DBHelper.STATUS_ACTIVE.equals(u.getStatus())){s.clear();go();return;}RecyclerView rv=findViewById(R.id.rvAdminJobs);rv.setLayoutManager(new LinearLayoutManager(this));AdminJobAdapter a=new AdminJobAdapter(rows,r->detail(r));rv.setAdapter(a);EditText search=findViewById(R.id.etAdminJobSearch);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){load(s.toString(),"");}public void afterTextChanged(Editable e){}});findViewById(R.id.btnBackAdminJobs).setOnClickListener(v->finish());load("","");}void load(String q,String st){rows.clear();rows.addAll(db.getAllJobsForAdmin(q,st,0));((RecyclerView)findViewById(R.id.rvAdminJobs)).getAdapter().notifyDataSetChanged();findViewById(R.id.tvAdminJobsEmpty).setVisibility(rows.isEmpty()?View.VISIBLE:View.GONE);}void detail(Map<String,Object>r){Intent i=new Intent(this,AdminJobDetailActivity.class);i.putExtra("JOB_ID",Integer.parseInt(String.valueOf(r.get("id"))));startActivity(i);}void go(){Intent i=new Intent(this,LoginActivity.class);i.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivity(i);finish();}}
